// src/ui/components/dialog.ts
var FOCUSABLE = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
function openDialog(parent, options2) {
  const previous = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const veil = el("div", "veil");
  const dialog = el("div", "dialog");
  dialog.setAttribute("role", "dialog");
  dialog.setAttribute("aria-modal", "true");
  const title = el("h2", void 0, options2.title);
  const titleId = `dlg-${Date.now()}`;
  title.id = titleId;
  dialog.setAttribute("aria-labelledby", titleId);
  const body = el("p", void 0, options2.body);
  const actions = el("div", "row");
  const confirm2 = el("button", "btn btn-primary", options2.confirmLabel);
  confirm2.type = "button";
  const cancel = options2.cancelLabel ? el("button", "btn", options2.cancelLabel) : null;
  if (cancel) cancel.type = "button";
  actions.append(confirm2);
  if (cancel) actions.append(cancel);
  dialog.append(title, body, actions);
  veil.append(dialog);
  parent.append(veil);
  const close = (result) => {
    stop();
    veil.remove();
    previous?.focus();
    if (result === "confirm") options2.onConfirm();
    else options2.onCancel();
  };
  const offConfirm = on(confirm2, "click", () => close("confirm"));
  const offCancel = cancel ? on(cancel, "click", () => close("cancel")) : () => void 0;
  const offKeys = on(dialog, "keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      close("cancel");
      return;
    }
    if (event.key !== "Tab") return;
    const items = [...dialog.querySelectorAll(FOCUSABLE)].filter((node) => !node.hasAttribute("disabled"));
    if (items.length === 0) return;
    const first = items[0];
    const last = items[items.length - 1];
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  });
  confirm2.focus();
  function stop() {
    offConfirm();
    offCancel();
    offKeys();
  }
  return () => {
    if (!veil.isConnected) return;
    stop();
    veil.remove();
    previous?.focus();
  };
}

