// src/ui/panels/learning-check.ts
var EMPTY = {
  version: 1,
  sessions: 0,
  pre: { A: 0, B: 0, C: 0 },
  post: { A: 0, B: 0, C: 0 },
  changedToB: 0
};
var preAnswer = null;
var preSkipped = false;
function shouldAskPre(ctx2) {
  const mission = ctx2.store.getState()?.mission;
  return mission?.level === "luna" && mission.day === 1 && ctx2.options.get().learningCheck && preAnswer === null && !preSkipped;
}
function shouldAskPost(ctx2) {
  return ctx2.options.get().learningCheck && preAnswer !== null && !preSkipped;
}
function readTotals() {
  try {
    const raw = localStorage.getItem("ea.learning.v1");
    if (!raw) return structuredClone(EMPTY);
    const parsed = JSON.parse(raw);
    if (!isTotals(parsed)) return structuredClone(EMPTY);
    return parsed;
  } catch {
    return structuredClone(EMPTY);
  }
}
function clearTotals() {
  try {
    localStorage.removeItem("ea.learning.v1");
  } catch {
  }
}
function mountLearningCheck(root2, ctx2, phase) {
  const veil = el("div", "veil");
  const dialog = el("div", "dialog");
  dialog.setAttribute("role", "dialog");
  dialog.setAttribute("aria-modal", "true");
  const title = el("h2");
  title.id = "learn-title";
  dialog.setAttribute("aria-labelledby", title.id);
  const options2 = el("div", "learn-options");
  const skip = el("button", "btn");
  skip.type = "button";
  dialog.append(title, options2, skip);
  veil.append(dialog);
  root2.append(veil);
  let closed = false;
  const close = () => {
    if (closed) return;
    closed = true;
    stop();
    veil.remove();
  };
  const paint = () => {
    title.textContent = ctx2.t("ui.learn.prompt");
    skip.textContent = ctx2.t("ui.learn.skip");
    options2.replaceChildren();
    for (const id of ["A", "B", "C"]) {
      const choice = el("button", "btn", ctx2.t(`ui.learn.${id}`));
      choice.type = "button";
      choice.addEventListener("click", () => {
        ctx2.audio.unlock();
        ctx2.audio.playSfx("sfx-confirm");
        record(phase, id);
        if (phase === "post") {
          options2.replaceChildren(el("p", "suggestion", ctx2.t("ui.learn.after")));
          skip.textContent = ctx2.t("ui.learn.continue");
          return;
        }
        close();
      });
      options2.append(choice);
    }
  };
  const offSkip = on(skip, "click", () => {
    if (phase === "pre" && preAnswer === null) preSkipped = true;
    close();
  });
  const offLang = ctx2.options.subscribe(paint);
  const offKeys = on(dialog, "keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      if (phase === "pre") preSkipped = true;
      close();
    }
  });
  function stop() {
    offSkip();
    offLang();
    offKeys();
  }
  paint();
  options2.querySelector("button")?.focus();
  return close;
}
function record(phase, answer) {
  if (phase === "pre") {
    preAnswer = answer;
    return;
  }
  const totals = readTotals();
  if (preAnswer) totals.pre[preAnswer] += 1;
  totals.post[answer] += 1;
  totals.sessions += 1;
  if (preAnswer && preAnswer !== "B" && answer === "B") totals.changedToB += 1;
  try {
    localStorage.setItem("ea.learning.v1", JSON.stringify(totals));
  } catch {
  }
  preAnswer = null;
}
function isTotals(value) {
  if (typeof value !== "object" || value === null) return false;
  const row = value;
  return row.version === 1 && typeof row.sessions === "number" && typeof row.changedToB === "number" && countRow(row.pre) && countRow(row.post);
}
function countRow(value) {
  if (typeof value !== "object" || value === null) return false;
  const row = value;
  return typeof row.A === "number" && typeof row.B === "number" && typeof row.C === "number";
}

