// tests/ui/mocks/runtime.ts
function summarizeHud(state2) {
  const crew3 = Math.max(1, state2.mission.crew.length);
  const margin = Math.min(
    Math.floor(state2.mission.resources.oxigeno / crew3),
    Math.floor(state2.mission.resources.agua / crew3),
    Math.floor(state2.mission.resources.alimentos / crew3)
  );
  const exposure = state2.mission.crew.reduce((max, member) => Math.max(max, member.exposure), 0);
  return {
    energia: {
      status: state2.mission.resources.energia >= 10 ? "seguro" : "preventivo",
      stored: state2.mission.resources.energia,
      cap: state2.mission.caps.energia,
      generationToday: 8,
      demandToday: 4
    },
    soporte: {
      status: margin <= 1 ? "critico" : margin < 4 ? "preventivo" : "seguro",
      marginDays: margin,
      limiting: "oxigeno"
    },
    proteccion: {
      status: exposure >= 75 ? "critico" : exposure >= 50 ? "preventivo" : "seguro",
      maxExposure: exposure,
      shelterReady: state2.mission.buildings.some((building2) => building2.type === "refugio"),
      alertInDays: 2
    }
  };
}
function computeForecast() {
  return [{ eventId: "luna-sep-1", type: "tormenta-solar", inDays: 2, durationDays: 1, radiationLevel: 2, sourceRef: "2017-09-10T16:25:00-SEP-001" }];
}
function previewEnergy() {
  return { generated: 8, demand: 4, shelterAffordable: true };
}
function previewAction(state2, action, data2) {
  if (action.type !== "BUILD") return null;
  if (state2.mission.phase !== "planning") return { code: "WRONG_PHASE", messageKey: "sim.error.WRONG_PHASE" };
  const def = data2.buildings[action.building];
  if (!def) return { code: "UNKNOWN_BUILDING", messageKey: "sim.error.UNKNOWN_BUILDING" };
  if (state2.mission.resources.materiales < def.cost) {
    return { code: "NO_MATERIALS", messageKey: "sim.error.NO_MATERIALS", params: { need: def.cost, have: state2.mission.resources.materiales } };
  }
  if (state2.mission.ap < def.apCost) return { code: "NO_AP", messageKey: "sim.error.NO_AP" };
  return null;
}

