function slider(options2) {
  const wrap = document.createElement("label");
  wrap.className = "option-row";
  const name = document.createElement("span");
  name.textContent = options2.label;
  const value = document.createElement("span");
  const input = document.createElement("input");
  input.type = "range";
  input.min = String(options2.min);
  input.max = String(options2.max);
  input.step = String(options2.step);
  input.value = String(options2.value);
  const field = document.createElement("span");
  field.className = "row";
  const paint = () => {
    value.textContent = input.value;
  };
  paint();
  input.addEventListener("input", () => {
    paint();
    options2.onInput(Number(input.value));
  });
  field.append(input, value);
  wrap.append(name, field);
  return wrap;
}
function setSliderValue(wrap, next) {
  const input = wrap.querySelector("input");
  const value = wrap.querySelector("span.row span");
  if (!input || document.activeElement === input) return;
  input.value = String(next);
  if (value) value.textContent = String(next);
}

// src/ui/components/toggle.ts
function toggle(options2) {
  const wrap = document.createElement("label");
  wrap.className = "option-row";
  const name = document.createElement("span");
  name.textContent = options2.label;
  const input = document.createElement("input");
  input.type = "checkbox";
  input.checked = options2.checked;
  input.addEventListener("change", () => options2.onChange(input.checked));
  wrap.append(name, input);
  return wrap;
}
function setToggle(wrap, checked) {
  const input = wrap.querySelector("input");
  if (!input || document.activeElement === input) return;
  input.checked = checked;
}

