    const scene2 = ctx2.flow.current().scene;
    const mission = ctx2.store.getState()?.mission.level;
    const visible = (scene2 === "mision" || scene2 === "pausa") && (mission === "luna" || mission === "marte");
    mapRoot.hidden = !visible;
    if (!visible || level !== mission || scene2 !== "mision") {
      cancelAnimationFrame(animation);
      active = null;
    }
    if (!visible) return;
    level = mission;
    const strings = copy[ctx2.options.get().language === "es" ? "es" : "en"];
